package main

import (
	"context"
	"database/sql"
	"errors"
	"net/http"
	"time"
)

// 1) 用非导出类型当 key，外部包拿不到，避免冲突
type ctxKey int

const traceIDKey ctxKey = 0

func handler(w http.ResponseWriter, r *http.Request, db *sql.DB) {
	// 2) r.Context() 在客户端断开 TCP 时由 net/http 自动 cancel
	parent := context.WithValue(r.Context(), traceIDKey, r.Header.Get("X-Trace-Id"))

	// 3) 给下游 DB 调用一个更短的子超时（父 deadline 再夹一刀）
	ctx, cancel := context.WithTimeout(parent, 300*time.Millisecond)
	defer cancel() // 必须 defer：及时 Stop timer 并从父 children 摘除

	rows, err := db.QueryContext(ctx, "SELECT id FROM orders WHERE uid=$1", 42)
	if err != nil {
		// 4) 用 errors.Is 区分超时还是主动取消
		switch {
		case errors.Is(err, context.DeadlineExceeded):
			http.Error(w, "db timeout", http.StatusGatewayTimeout)
		case errors.Is(err, context.Canceled):
			// 客户端早断开，不用回写
			return
		default:
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
		return
	}
	defer rows.Close()
}

// 5) 下游若是自己写的循环，必须 select Done，否则收不到取消
func poll(ctx context.Context, tick time.Duration) error {
	t := time.NewTicker(tick)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return ctx.Err() // Canceled or DeadlineExceeded
		case <-t.C:
			// do work
		}
	}
}
